from typing import List

def getMinimumCost(time: List[int], cost: List[int]) -> int:
    n = len(time)
    INF = float('inf')
    # dp[j]: 已"覆盖" j 个任务（上限截到 n）时的最小花费
    dp = [0] + [INF] * n
    for t, c in zip(time, cost):
        for j in range(n, -1, -1):
            if dp[j] < INF:
                nj = min(n, j + t + 1)
                if dp[j] + c < dp[nj]:
                    dp[nj] = dp[j] + c
    return dp[n]
